    TRUNCATE TABLE glosa;
    TRUNCATE TABLE CTM;
    TRUNCATE TABLE dirigido;
    TRUNCATE TABLE trazo;
    TRUNCATE TABLE FACTURA;
    TRUNCATE TABLE DescargaDesp;
    TRUNCATE TABLE CTMDESCARGA;
    TRUNCATE TABLE HistoriaDescarga;
    TRUNCATE TABLE HistoriaDescargaSalida;
    TRUNCATE TABLE comprobante;
    TRUNCATE TABLE FacturasCreadas;
    TRUNCATE TABLE partidasglosa;
    TRUNCATE TABLE MensajeDescarga;
    TRUNCATE TABLE Desperdicios;
    TRUNCATE TABLE pdesperdicios;
    TRUNCATE TABLE cDescargaDirigida;
    TRUNCATE TABLE DescDirctma;
    TRUNCATE TABLE DescDirDesperdicios;
    TRUNCATE TABLE ECargaMaterial;
    TRUNCATE TABLE errCargaFactura;
    TRUNCATE TABLE errorGlosa;
    DELETE FROM ErroresValidacionInventarioInicial;
    DELETE FROM ValidacionInventarioInicial;
    TRUNCATE TABLE ActivoFijo;

    -- ============================================
    -- 1. CATALOGOS BASE
    -- ============================================

    -- 1.1 Empresa (datos reales de la auditoria)

    -- 1.2 Almacenes (3)

    -- 1.3 Unidades

    -- 1.4 Categorias

    -- 1.5 TipoMaterial (catalogo usado por material.tipomaterial)

    -- 1.6 Agentes aduanales (2)

    -- 1.7 Clientes (5) - compradores de producto terminado (exportacion)

    -- 1.8 Proveedores (5) - azucar y empaque

    -- 1.9 Materiales (2) - datos reales del reporte de auditoria

    -- 1.10 Factores de conversion de material

    -- 1.11 Productos (204) - fraccion 17049099, datos reales de auditoria

    -- 1.12 Factores de conversion de producto (muestra)

    -- 1.13 Plantas

    -- 1.14 Periodos

    -- 1.15 Settings

    -- 1.16 Mensajes de inicio

    -- 1.17 Activos fijos (4) - maquinaria de confiteria

    -- ============================================
    -- 2. TABLAS STAGE (entrada de carga)
    -- ============================================



    -- ============================================
    -- 3. IMPORTACIONES (2 cabeceras reales)
    -- ============================================

    -- 3.2 partidas (lineas de pedimento de importacion)
    --     (A) `500017` AZUCAR ESTANDAR: Cantidad incluye remanente -> saldo vivo.
    --     (D) `500005` AZUCAR REFINADA: Cantidad == utilizado -> saldo 0.

    -- ============================================
    -- 4. EXPORTACIONES
    -- ============================================

    -- 4.1 salidas (660 cabeceras reales)

    -- 4.2 psalidas (3392 partidas de exportacion reales)




    -- ============================================
    -- 5. DESCARGA (material utilizado): 3866 relaciones reales impo -> expo
    -- ============================================




    -- ============================================
    -- 6. COMPLEMENTOS / CONSECUTIVOS
