    -- 6.1 HistoriaDescarga (una fila por material)

    COMMIT;
    PRINT '=== SEED CALE_IMMEX CARGADO OK ===';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    PRINT '=== SEED CALE_IMMEX FALLO: ROLLBACK ===';
    THROW;
END CATCH;
GO

-- ============================================
-- 7. VERIFICACION (solo lectura)
-- ============================================
PRINT '--- Conteos por tabla ---';
SELECT 'material' AS tabla, COUNT(*) AS filas FROM material
UNION ALL SELECT 'productos',    COUNT(*) FROM productos
UNION ALL SELECT 'Importaciones',COUNT(*) FROM Importaciones
UNION ALL SELECT 'partidas',     COUNT(*) FROM partidas
UNION ALL SELECT 'salidas',      COUNT(*) FROM salidas
UNION ALL SELECT 'psalidas',     COUNT(*) FROM psalidas
UNION ALL SELECT 'descarga',     COUNT(*) FROM descarga;

PRINT '--- Materiales (datos reales de auditoria) ---';
SELECT materialkey, clave, descripcion, fraccion, unidadt FROM material ORDER BY materialkey;

PRINT '--- Partidas: escenario (A) saldo vivo y (D) saldo cero ---';
SELECT Partidakey, Clave, Cantidad, Saldo,
       CASE WHEN Saldo = 0 THEN 'D - TOTALMENTE DESCARGADA'
            WHEN Saldo > 0 AND Saldo < Cantidad THEN 'A - DESCARGA PARCIAL'
            ELSE 'OTRO' END AS escenario
FROM partidas ORDER BY Partidakey;

PRINT '--- Integridad: saldos fuera de rango (esperado 0) ---';
SELECT COUNT(*) AS saldos_invalidos FROM partidas WHERE Saldo < 0 OR Saldo > Cantidad;

PRINT '--- Integridad: descargas huerfanas (esperado 0) ---';
SELECT COUNT(*) AS descargas_huerfanas FROM descarga d
WHERE NOT EXISTS (SELECT 1 FROM Importaciones i WHERE i.Ipedimentokey = d.Entradalink)
   OR NOT EXISTS (SELECT 1 FROM partidas p WHERE p.Partidakey = d.Pentradalink)
   OR NOT EXISTS (SELECT 1 FROM salidas s WHERE s.SalidaKey = d.Salidalink)
   OR NOT EXISTS (SELECT 1 FROM psalidas ps WHERE ps.Psalidakey = d.Psalidalink);

PRINT '--- Material utilizado acumulado vs cantidad importada ---';
SELECT p.Clave,
       p.Cantidad AS importado,
       (SELECT SUM(d.CantUtil) FROM descarga d WHERE d.Pentradalink = p.Partidakey) AS utilizado,
       p.Saldo
FROM partidas p ORDER BY p.Partidakey;

PRINT '--- Usuarios (deben conservarse intactos) ---';
SELECT COUNT(*) AS usuarios FROM usuarios;
GO
